-- Phase 1: Schema metadata registry for purchases column consolidation.
-- Source: docs/purchases-field-classification.csv (owner-approved 2026-06-26).
-- Rollback: DROP TABLE IF EXISTS purchase_field_registry;

SET @exists := (
  SELECT COUNT(*) FROM information_schema.tables
  WHERE table_schema = DATABASE() AND table_name = 'purchase_field_registry'
);
SET @sql := IF(@exists = 0,
'CREATE TABLE purchase_field_registry (
  id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,
  column_name VARCHAR(128) NOT NULL,
  kotlin_property VARCHAR(128) NULL,
  json_api_key VARCHAR(255) NULL,
  mysql_type VARCHAR(64) NULL,
  classification VARCHAR(64) NOT NULL,
  target_phase VARCHAR(16) NULL,
  drop_candidate VARCHAR(16) NULL,
  is_indexed VARCHAR(64) NULL,
  query_critical VARCHAR(16) NULL,
  car_brand_mapping_column VARCHAR(128) NULL,
  cost_code_or_json_key VARCHAR(128) NULL,
  notes TEXT NULL,
  review_decision VARCHAR(32) NULL,
  created_at TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  UNIQUE KEY uk_purchase_field_registry_column (column_name),
  KEY idx_pfr_classification (classification),
  KEY idx_pfr_target_phase (target_phase)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci',
'SELECT 1');
PREPARE stmt FROM @sql;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;

ON DUPLICATE KEY UPDATE
  kotlin_property = VALUES(kotlin_property),
  json_api_key = VALUES(json_api_key),
  mysql_type = VALUES(mysql_type),
  classification = VALUES(classification),
  target_phase = VALUES(target_phase),
  drop_candidate = VALUES(drop_candidate),
  is_indexed = VALUES(is_indexed),
  query_critical = VALUES(query_critical),
  car_brand_mapping_column = VALUES(car_brand_mapping_column),
  cost_code_or_json_key = VALUES(cost_code_or_json_key),
  notes = VALUES(notes),
  review_decision = VALUES(review_decision);
